// cos_rando_test_R7_3a (docs/RANDOMIZER_PLAN.md step R7.3a): the enemy randomizer's data tables
// (features/rando/pc_rando_enemy_data.h, generated by native/tools/rando/gen_enemy_data.py from wwrando
// 1.10.0_9775811). Checks the counts of every table, that the slices are contiguous and in order, that
// every Original enemy names a type and every path parses, that every requirement string ("Original
// requirements" of the 222 groups, "Requirements to defeat" of the 46 types) compiles and evaluates
// with R1.1's ReqLogic without an error, EnemyCategory matching against masks computed by wwrando's own
// EnemyCategory class, the bitfield helpers, and spot values.
// Prints "ok" and exits 0 when every check holds.
#include "rando_test.h"

#include "pc_rando_data.h"
#include "pc_rando_enemy_data.h"
#include "pc_rando_logic_expr.h"
#include "pc_rando_options.h"

#include <cstring>
#include <set>
#include <string>
#include <vector>

using namespace pcr;

namespace {

bool eq(const char* a, const char* b) { return a != nullptr && b != nullptr && std::strcmp(a, b) == 0; }

void testTypes() {
    RT_CHECK_EQ(enemy_types().size, (size_t)46);
    std::set<std::string> names;
    size_t nextParticle = 0;
    int allowFrom = 0, allowTo = 0;
    for (const EnemyType& t : enemy_types()) {
        RT_CHECK(names.insert(t.pretty_name).second);
        RT_CHECK_EQ((size_t)t.first_particle, nextParticle);
        nextParticle += t.num_particles;
        RT_CHECK(t.num_categories >= 1 && t.num_categories <= 3);
        RT_CHECK(t.requirements != nullptr && t.requirements[0] != '\0');
        RT_CHECK(t.mem_first >= t.mem_subsequent);
        // Every actor has a class, and every switch/path param name is a bitfield of it.
        const char* cls = actor_class_name(t.actor_name);
        RT_CHECK(cls != nullptr);
        for (const char* p : {t.spawn_switch_param, t.death_switch_param, t.path_param}) {
            if (p != nullptr) {
                RT_CHECK(actor_param(cls, p) != nullptr);
            }
        }
        allowFrom += t.allow_from;
        allowTo += t.allow_to;
    }
    RT_CHECK_EQ(nextParticle, enemy_particle_ids().size);
    RT_CHECK_EQ(allowFrom, 41);
    RT_CHECK_EQ(allowTo, 37);

    const EnemyType& bk = enemy_types()[0];
    RT_CHECK(eq(bk.pretty_name, "Bokoblin") && eq(bk.actor_name, "Bk"));
    RT_CHECK_EQ(bk.params, 0xFFFFFF00u);
    RT_CHECK_EQ(bk.x_rot, (uint16_t)0x001F);
    RT_CHECK_EQ(bk.z_rot, (uint16_t)0x00FF);
    RT_CHECK(eq(bk.requirements, "Can Defeat Bokoblins"));
    RT_CHECK_EQ((int)bk.num_categories, 2);
    RT_CHECK(bk.categories[0] == EnemyCat::Ground && bk.categories[1] == EnemyCat::Pot);
    RT_CHECK_EQ(bk.mem_first, 53280u);
    RT_CHECK_EQ(bk.mem_subsequent, 23088u);
    RT_CHECK(eq(bk.spawn_switch_param, "spawn_condition_switch"));
    RT_CHECK(eq(bk.death_switch_param, "disable_spawn_on_death_switch"));
    RT_CHECK(eq(bk.path_param, "path_index"));
    RT_CHECK(bk.allow_near_pits && bk.killable_thrown && bk.killable_bomb_flowers);
    RT_CHECK_EQ(enemy_type_particles(bk).size, (size_t)0);

    int dark = enemy_type_index("Dark ChuChu");
    RT_CHECK(dark >= 0);
    Span<uint16_t> dp = enemy_type_particles(enemy_types()[dark]);
    RT_CHECK(dp.size == 2 && dp[0] == 33448 && dp[1] == 33449);
    RT_CHECK(!enemy_types()[dark].allow_from && !enemy_types()[dark].allow_to);
    RT_CHECK_EQ(enemy_types()[dark].death_switch_param, (const char*)nullptr);

    const EnemyType& last = enemy_types()[45];
    RT_CHECK(eq(last.pretty_name, "Floormaster") && eq(last.actor_name, "Fmastr2"));
    RT_CHECK_EQ(last.params, 0xFFFF02FFu);
    RT_CHECK_EQ(enemy_type_index("No Such Enemy"), -1);
}

void testLocations() {
    RT_CHECK_EQ(enemy_stages().size, (size_t)82);
    RT_CHECK_EQ(enemy_groups().size, (size_t)222);
    RT_CHECK_EQ(enemy_locations().size, (size_t)1275);
    RT_CHECK_EQ(enemy_alldie_paths().size, (size_t)13);
    RT_CHECK_EQ(enemy_modify_actors().size, (size_t)3);
    RT_CHECK_EQ(enemy_add_actors().size, (size_t)5);
    RT_CHECK_EQ(enemy_remove_paths().size, (size_t)2);

    int sea = 0;
    std::set<std::string> keys;
    size_t nextGroup = 0;
    for (const EnemyStage& s : enemy_stages()) {
        RT_CHECK(keys.insert(s.key).second);
        RT_CHECK_EQ((size_t)s.first_group, nextGroup);
        RT_CHECK(s.num_groups >= 1);
        nextGroup += s.num_groups;
        sea += std::strncmp(s.key, "sea/", 4) == 0;
    }
    RT_CHECK_EQ(nextGroup, (size_t)222);
    RT_CHECK_EQ(sea, 35);

    size_t nE = 0, nA = 0, nM = 0, nN = 0, nR = 0;
    int mustDefeat = 0, freeMem = 0, throwable = 0, bombs = 0, withAlldie = 0, withModify = 0, withAdd = 0,
        withRemove = 0;
    for (size_t gi = 0; gi < enemy_groups().size; gi++) {
        const EnemyGroup& g = enemy_groups()[gi];
        const EnemyStage& s = enemy_stages()[g.stage];
        RT_CHECK(gi >= s.first_group && gi < (size_t)s.first_group + s.num_groups);
        RT_CHECK_EQ((size_t)g.first_enemy, nE);
        RT_CHECK_EQ((size_t)g.first_alldie, nA);
        RT_CHECK_EQ((size_t)g.first_modify, nM);
        RT_CHECK_EQ((size_t)g.first_add, nN);
        RT_CHECK_EQ((size_t)g.first_remove, nR);
        RT_CHECK(g.num_enemies >= 1);
        nE += g.num_enemies;
        nA += g.num_alldie;
        nM += g.num_modify;
        nN += g.num_add;
        nR += g.num_remove;
        RT_CHECK(g.original_req != nullptr && g.original_req[0] != '\0');
        mustDefeat += g.must_defeat;
        freeMem += g.free_memory >= 0;
        throwable += g.has_throwable;
        bombs += g.has_bomb_flowers;
        withAlldie += g.num_alldie > 0;
        withModify += g.num_modify > 0;
        withAdd += g.num_add > 0;
        withRemove += g.num_remove > 0;
        for (const EnemyLocation& e : enemy_group_locations(g)) {
            RT_CHECK_EQ((size_t)e.group, gi);
        }
    }
    RT_CHECK_EQ(nE, (size_t)1275);
    RT_CHECK_EQ(nA, (size_t)13);
    RT_CHECK_EQ(nM, (size_t)3);
    RT_CHECK_EQ(nN, (size_t)5);
    RT_CHECK_EQ(nR, (size_t)2);
    RT_CHECK_EQ(freeMem, 42);
    RT_CHECK_EQ(throwable, 22);
    RT_CHECK_EQ(bombs, 1);
    RT_CHECK_EQ(withAlldie, 13);
    RT_CHECK_EQ(withModify, 3);
    RT_CHECK_EQ(withAdd, 3);
    RT_CHECK_EQ(withRemove, 2);
    RT_CHECK(mustDefeat > 0 && mustDefeat < 222);

    // Every location: its Original enemy is a type (and the index agrees), its category string parses to
    // the stored category, its path is an Actor path whose stage matches the key.
    int pos = 0, off = 0, yrot = 0, yoff = 0, layered = 0;
    for (const EnemyLocation& e : enemy_locations()) {
        RT_CHECK_EQ(enemy_type_index(e.original_enemy), (int)e.original_type);
        EnemyCat c;
        uint8_t bits;
        RT_CHECK(parse_enemy_category(e.category_raw, &c, &bits));
        RT_CHECK(c == e.category && bits == e.conds);
        RT_CHECK(e.path.chunk == EnemyChunk::Actor);
        RT_CHECK(e.path.raw != nullptr && e.path.file != nullptr);
        const char* key = enemy_stages()[enemy_groups()[e.group].stage].key;
        if (std::strncmp(key, "sea/", 4) == 0) {
            RT_CHECK(eq(e.path.stage, "sea") && eq(key + 4, e.path.arc));
        } else {
            RT_CHECK(eq(e.path.stage, key));
        }
        std::string rebuilt = std::string(e.path.file);
        if (e.path.layer >= 0) {
            char b[16];
            std::snprintf(b, sizeof b, "/Layer%x", e.path.layer);
            rebuilt += b;
        }
        char b[16];
        std::snprintf(b, sizeof b, "/Actor%03X", e.path.index);
        rebuilt += b;
        RT_CHECK_EQ(rebuilt, std::string(e.path.raw));
        pos += (e.flags & ELOC_POSITION) != 0;
        off += (e.flags & ELOC_POSITION_OFFSET) != 0;
        yrot += (e.flags & ELOC_Y_ROTATION) != 0;
        yoff += (e.flags & ELOC_Y_ROTATION_OFFSET) != 0;
        layered += e.path.layer >= 0;
    }
    RT_CHECK_EQ(pos, 55);
    RT_CHECK_EQ(off, 93);
    RT_CHECK_EQ(yrot, 2);
    RT_CHECK_EQ(yoff, 4);
    RT_CHECK(layered > 0);

    // Spot values.
    const EnemyStage& amori = enemy_stages()[0];
    RT_CHECK(eq(amori.key, "A_mori") && amori.num_groups == 1);
    const EnemyGroup& g0 = enemy_groups()[0];
    RT_CHECK(!g0.must_defeat);
    RT_CHECK(eq(g0.original_req, "Can Defeat Morths & Can Defeat Mothulas & Can Defeat Moblins")); // folded
    RT_CHECK_EQ((int)g0.num_enemies, 9);
    RT_CHECK_EQ(g0.free_memory, -1);
    const EnemyLocation& e0 = enemy_locations()[0];
    RT_CHECK(eq(e0.original_enemy, "Morth") && e0.category == EnemyCat::Ground && e0.conds == 0);
    RT_CHECK(eq(e0.path.file, "A_mori/Room0.arc") && e0.path.room == 0 && e0.path.layer == 2 && e0.path.index == 0);

    int tyu = enemy_stage_index("TyuTyu");
    RT_CHECK(tyu >= 0);
    RT_CHECK_EQ(enemy_groups()[enemy_stages()[tyu].first_group].free_memory, 493040);
    RT_CHECK_EQ(enemy_stage_index("sea"), -1);
    RT_CHECK(enemy_stage_index("sea/Room44.arc") >= 0);

    // ITest63: two +0x4000 and two -0x4000 Y rotation offsets.
    int plus = 0, minus = 0;
    for (const EnemyLocation& e : enemy_locations()) {
        if (e.flags & ELOC_Y_ROTATION_OFFSET) {
            RT_CHECK(eq(e.path.stage, "ITest63"));
            plus += e.y_rot_offset == 16384;
            minus += e.y_rot_offset == -16384;
        }
        if (eq(e.path.raw, "M_Dra09/Room9.arc/Actor001")) {
            RT_CHECK((e.flags & ELOC_Y_ROTATION) && e.y_rot == 51882);
        }
    }
    RT_CHECK(plus == 2 && minus == 2);

    // Optional group fields.
    const EnemyActorData& door = enemy_modify_actors()[2];
    RT_CHECK(eq(door.path.raw, "TF_01/Stage.arc/ScalableDoor005") && door.path.chunk == EnemyChunk::ScalableDoor);
    RT_CHECK(door.path.room == -1 && door.path.layer == -1 && eq(door.path.arc, "Stage.arc"));
    RT_CHECK_EQ((int)door.flags, (int)(EACT_NAME | EACT_PARAMS));
    RT_CHECK(eq(door.name, "door10") && door.params == 268431394u);
    const EnemyActorData& m1 = enemy_modify_actors()[1];
    RT_CHECK(eq(m1.path.raw, "M_NewD2/Room11.arc/Actor004"));
    RT_CHECK_EQ((int)m1.flags, (int)(EACT_PARAMS | EACT_POSITION));
    RT_CHECK(m1.params == 25149953u && m1.position[0] == -3953.0 && m1.position[1] == 500.0 && m1.position[2] == 1426.0);
    const EnemyActorData& pot = enemy_add_actors()[0];
    RT_CHECK(pot.path.raw == nullptr && eq(pot.name, "ootubo1") && pot.params == 1904198207u);
    RT_CHECK(pot.z_rot == 255 && (pot.flags & EACT_POSITION) && pot.position[0] == 3886.0);
    const EnemyActorData& sw = enemy_add_actors()[3];
    RT_CHECK(eq(sw.name, "AND_SW2") && sw.params == 2552365058u && sw.x_rot == 255);
    RT_CHECK_EQ((int)sw.flags, (int)(EACT_NAME | EACT_PARAMS | EACT_X_ROTATION));
    RT_CHECK(eq(enemy_remove_paths()[1].raw, "SirenMB/Room23.arc/ScalableObject000"));
    RT_CHECK(enemy_remove_paths()[1].chunk == EnemyChunk::ScalableObject && enemy_remove_paths()[1].room == 23);
    RT_CHECK(eq(enemy_alldie_paths()[0].raw, "Abship/Room0.arc/Actor005"));
    for (const EnemyActorPath& p : enemy_alldie_paths()) {
        RT_CHECK(p.chunk == EnemyChunk::Actor);
    }
    int tf01 = enemy_stage_index("TF_01");
    RT_CHECK(tf01 >= 0);
    const EnemyGroup& tg = enemy_groups()[enemy_stages()[tf01].first_group];
    RT_CHECK(tg.num_add == 2 && eq(enemy_group_adds(tg)[0].name, "ALLdie"));
    RT_CHECK(tg.num_modify == 1 && eq(enemy_group_modifies(tg)[0].name, "door10"));
}

void testConstants() {
    RT_CHECK_EQ(enemy_max_species_per_stage(), 10);
    RT_CHECK_EQ(enemy_max_species_per_group(), 5);
    RT_CHECK_EQ(enemy_max_redos_per_stage(), 50);
    RT_CHECK_EQ(enemy_max_redos_per_room(), 20);
    RT_CHECK_EQ(enemy_min_free_space_per_room(), 60000);
    RT_CHECK_EQ(enemy_two_room_stages().size, (size_t)15);
    RT_CHECK(enemy_is_two_room_stage("M_NewD2") && enemy_is_two_room_stage("TF_06"));
    RT_CHECK(!enemy_is_two_room_stage("A_mori") && !enemy_is_two_room_stage("sea"));
    // The two-room stages that have enemy groups.
    int withGroups = 0;
    for (const char* s : enemy_two_room_stages()) {
        withGroups += enemy_stage_index(s) >= 0;
    }
    RT_CHECK_EQ(withGroups, 12);
}

// Masks of the types allowed per location category string, computed by wwrando's own EnemyCategory
// (`category in [EnemyCategory(c, type) for c in type["Placement categories"]]`); bit i = type i.
struct CatMask {
    const char* category;
    uint64_t mask;
};
const CatMask kCatMasks[] = {
    {"Ground", 0x000033FFFFF1FBFFULL},
    {"Ceiling", 0x000002600001827EULL},
    {"Pot", 0x000033FFFFF1FBFFULL},
    {"Air", 0x0000026000018240ULL},
    {"Ground:HasPit", 0x000030EF0471FBFFULL},
    {"Ceiling:ChecksConditionSwitch", 0x000000600001827EULL},
    {"Ground:ChecksConditionSwitch,SetsDeathSwitch", 0x0000001300700381ULL},
    {"Ground:SetsDeathSwitch", 0x0000031300700381ULL},
    {"Ground:ChecksConditionSwitch", 0x000030730471DBFFULL},
    {"Water", 0x0000000000020000ULL},
    {"Sea", 0x00000C00000C0400ULL},
    {"Ground:SetsDeathSwitch,HasPit", 0x0000000300700381ULL},
    {"StationaryAir:SetsDeathSwitch,HasPit", 0x0000000000100200ULL},
    {"Air:HasPit", 0x0000006000018240ULL},
    {"Water:HasPit", 0x0000000000020000ULL},
};

void testCategories() {
    // The 15 distinct location category strings, in first-seen order, are exactly the table's.
    std::vector<std::string> seen;
    for (const EnemyLocation& e : enemy_locations()) {
        bool found = false;
        for (const std::string& s : seen) {
            found = found || s == e.category_raw;
        }
        if (!found) {
            seen.push_back(e.category_raw);
        }
    }
    RT_CHECK_EQ(seen.size(), sizeof kCatMasks / sizeof kCatMasks[0]);
    for (size_t i = 0; i < seen.size() && i < sizeof kCatMasks / sizeof kCatMasks[0]; i++) {
        RT_CHECK_EQ(seen[i], std::string(kCatMasks[i].category));
    }
    for (const CatMask& cm : kCatMasks) {
        EnemyCat c;
        uint8_t bits;
        RT_CHECK(parse_enemy_category(cm.category, &c, &bits));
        uint64_t got = 0;
        for (size_t t = 0; t < enemy_types().size; t++) {
            if (enemy_type_allowed_in(enemy_types()[t], c, bits)) {
                got |= 1ULL << t;
            }
        }
        if (got != cm.mask) {
            std::fprintf(stderr, "FAIL category %s: %016llX vs %016llX\n", cm.category, (unsigned long long)got,
                         (unsigned long long)cm.mask);
        }
        RT_CHECK(got == cm.mask);
    }
    EnemyCat c;
    uint8_t bits;
    RT_CHECK(!parse_enemy_category("Ground:Flying", &c, &bits));
    RT_CHECK(!parse_enemy_category("Ground:", &c, &bits));
    RT_CHECK(!parse_enemy_category("Floor", &c, &bits));
    RT_CHECK(parse_enemy_category("StationaryAir", &c, &bits) && c == EnemyCat::StationaryAir && bits == 0);
    RT_CHECK(eq(enemy_cat_name(EnemyCat::Ceiling), "Ceiling"));
}

void testRequirements() {
    Options opts;
    std::vector<std::string> items;
    for (size_t i = 0; i < default_logic_item_count(); i++) {
        items.push_back(logic_item_names()[i]);
    }
    ReqLogic L;
    RT_CHECK(L.init(opts, items));
    RT_CHECK(!L.failed());
    int compiled = 0;
    auto check = [&](const char* req, const char* what) {
        int expr = L.compile(req);
        RT_CHECK(expr >= 0);
        // Evaluating resolves every token (all children are evaluated), so an unknown name errors here.
        if (expr >= 0) {
            (void)L.checkExpr(expr);
            ItemsNeeded need;
            L.itemsNeededForExpr(expr, need);
        }
        if (L.failed()) {
            std::fprintf(stderr, "FAIL requirement of %s: %s: %s\n", what, req, L.error().c_str());
            RT_CHECK(false);
        } else {
            compiled++;
        }
    };
    for (const EnemyGroup& g : enemy_groups()) {
        check(g.original_req, enemy_group_locations(g)[0].path.raw);
    }
    for (const EnemyType& t : enemy_types()) {
        check(t.requirements, t.pretty_name);
    }
    RT_CHECK_EQ(compiled, 222 + 46);

    // The check above can fail: an unknown name is an error.
    ReqLogic bad;
    RT_CHECK(bad.init(opts, items));
    int expr = bad.compile("Can Defeat Bokoblins & Can Defeat Nonexistent Enemies");
    RT_CHECK(expr >= 0);
    (void)bad.checkExpr(expr);
    RT_CHECK(bad.failed());
}

void testActors() {
    RT_CHECK_EQ(actor_infos().size, (size_t)824);
    RT_CHECK(eq(actor_class_name("Bk"), "d_a_bk"));
    RT_CHECK(eq(actor_class_name("ALLdie"), "d_a_alldie"));
    RT_CHECK(eq(actor_class_name("Homen1"), "d_a_obj_homen"));
    RT_CHECK_EQ(actor_class_name("NoSuchActor"), (const char*)nullptr);
    for (const ActorInfo& a : actor_infos()) {
        for (const char* p = a.class_name; *p; p++) {
            RT_CHECK(!(*p >= 'A' && *p <= 'Z')); // lower-cased as data_tables.py
        }
    }
    const ActorInfo* kb = nullptr;
    for (const ActorInfo& a : actor_infos()) {
        if (eq(a.name, "Kbota_B")) {
            kb = &a;
        }
    }
    RT_CHECK(kb != nullptr && eq(kb->class_name, "d_a_obj_swpush") && kb->actor_id == 29 && kb->subtype == 1);

    size_t next = 0;
    std::set<std::string> classes;
    for (const ActorParamClass& c : actor_param_classes()) {
        RT_CHECK(classes.insert(c.class_name).second);
        RT_CHECK_EQ((size_t)c.first_field, next);
        next += c.num_fields;
    }
    RT_CHECK_EQ(next, actor_param_fields().size);
    // Every enemy actor's class and the extra ones are emitted.
    for (const EnemyType& t : enemy_types()) {
        RT_CHECK(classes.count(actor_class_name(t.actor_name)) == 1);
    }
    for (const char* c : {"d_a_obj_homen", "d_a_alldie", "d_a_andsw0", "d_a_andsw2", "d_a_obj_swpush"}) {
        RT_CHECK(classes.count(c) == 1);
    }
    // The fields enemies.py uses for the extra actors.
    RT_CHECK(actor_param("d_a_obj_homen", "enemy_to_spawn") != nullptr);
    RT_CHECK(actor_param("d_a_alldie", "switch_to_set") != nullptr);
    RT_CHECK(actor_param("d_a_andsw0", "switch_to_set") != nullptr);
    RT_CHECK(actor_param("d_a_andsw2", "switch_to_set") != nullptr);
    RT_CHECK(actor_param("d_a_obj_swpush", "switch_to_set") != nullptr);
    RT_CHECK(actor_param("d_a_rd", "dont_check_enable_spawn_switch") != nullptr);
    RT_CHECK(actor_param("d_a_st", "stalfos_type") != nullptr);
    RT_CHECK(actor_param("d_a_fm", "type") != nullptr);
    RT_CHECK_EQ(actor_param("d_a_bk", "no_such_field"), (const ActorParamField*)nullptr);
    RT_CHECK_EQ(actor_param("d_a_tsubo", "type"), (const ActorParamField*)nullptr); // not emitted

    // dzx.py bitfield semantics.
    const ActorParamField* alldie = actor_param("d_a_alldie", "switch_to_set");
    RT_CHECK(alldie != nullptr && alldie->bitfield == ActorBitfield::params && alldie->mask == 0x0000FF00u);
    if (alldie != nullptr) {
        RT_CHECK_EQ(actor_param_get(*alldie, 0xFFFF99FFu), 0x99u);
        RT_CHECK_EQ(actor_param_set(*alldie, 0xFFFFFFFFu, 0x19u), 0xFFFF19FFu);
        RT_CHECK_EQ(actor_param_set(*alldie, 0x00000000u, 0x1FFu), 0x0000FF00u); // masked
    }
}

} // namespace

int main() {
    testTypes();
    testLocations();
    testConstants();
    testCategories();
    testRequirements();
    testActors();
    return rt::finish();
}
